basicCode.react:
import { QuotaBanner } from "@/components/ui/quota-banner";

<QuotaBanner
  quota={{ used: 168, limit: 200 }}
  renewsIn={horizonte}
  actions={[botao]}
  labels={rotulos}
/>

withLabelsCode.web:
// O HORIZONTE CHEGA ESCRITO. Quantas casas, qual separador e como se abrevia
// hora e minuto são decisão de idioma e de lugar — quem sabe disso é quem
// mede, e não um componente que decidiria idioma em cinco lugares.
const unidade = (valor, nome) =>
  new Intl.NumberFormat('pt-BR', {
    style: 'unit',
    unit: nome,
    unitDisplay: 'short',
  }).format(valor);

const horizonte = `${unidade(3, 'hour')} ${unidade(12, 'minute')}`;

// E o texto da peça: de qual cota se trata, o que é contado, a palavra que
// acompanha o resto, o que dizer quando acabou, a palavra que antecede o
// horizonte, a que liga a razão, e a palavra de cada nível.
const rotulos = {
  title: 'Cota do plano',
  unit: 'mensagens',
  left: 'restantes',
  exhausted: 'Cota esgotada',
  renews: 'Renova em',
  of: 'de',
  level: { normal: 'Com folga', warning: 'Perto do fim', critical: 'No fim' },
};

extensibilityCode.web:
// O RESTO NUNCA É NEGATIVO. Quem passou do teto não tem "menos que nada" de
// cota, tem cota nenhuma — e é por isso que a subtração mora aqui:
remainingUnits(168, 200);      // 32
remainingUnits(214, 200);      // 0, e não -14

// TETO QUE NÃO É TETO não deixa nada restando, e a razão sai como ausência:
remainingUnits(168, 0);        // 0
spentFraction(168, 0);         // null

// A RAZÃO É O PAR DO RESTO: resto zero e razão cheia são a mesma notícia.
spentFraction(214, 200);       // 1

// O LIMIAR É O MESMO DAS OUTRAS MEDIÇÕES, e é exato — três quartos já é aviso:
fractionLevel(0.74);           // 'normal'
fractionLevel(0.75);           // 'warning'
fractionLevel(0.9);            // 'critical'

// E o por cento que o medidor desenha é travado nas duas pontas:
fractionPercent(0.999);        // 99
fractionPercent(1);            // 100

customizationCode.web:
.nds-quota-banner {
  max-inline-size: 28rem;
}

/* A cor é REFORÇO, e não a pista: a palavra do nível e a razão do rodapé são o
   que descreve. Mexer na cor não muda o que chega a quem ouve. */
.nds-quota-banner[data-level="warning"] {
  --nds-quota-banner-color: var(--chart-4);
}

