withLabelsCode.web:
// THE HORIZON ARRIVES WRITTEN. How many digits, which separator and how hours
// and minutes are abbreviated are decisions of language and place — whoever
// knows that is whoever measured, not a component that would decide language
// in five places at once.
const unit = (value, name) =>
  new Intl.NumberFormat('en', {
    style: 'unit',
    unit: name,
    unitDisplay: 'short',
  }).format(value);

const horizon = `${unit(3, 'hour')} ${unit(12, 'minute')}`;

// And the text of the piece: which allowance it is, what is counted, the word
// that goes with the remainder, what to say when it ran out, the word before
// the horizon, the one that ties the ratio, and the word for each level.
const labels = {
  title: 'Plan quota',
  unit: 'messages',
  left: 'left',
  exhausted: 'Quota used up',
  renews: 'Renews in',
  of: 'of',
  level: { normal: 'Room to spare', warning: 'Near the end', critical: 'At the end' },
};

extensibilityCode.web:
// THE REMAINDER IS NEVER NEGATIVE. Whoever went past the ceiling does not have
// "less than nothing" of allowance, they have none — hence the subtraction here:
remainingUnits(168, 200);      // 32
remainingUnits(214, 200);      // 0, not -14

// A CEILING THAT IS NOT A CEILING leaves nothing behind, and the ratio is absent:
remainingUnits(168, 0);        // 0
spentFraction(168, 0);         // null

// THE RATIO IS THE TWIN OF THE REMAINDER: zero left and a full ratio are one fact.
spentFraction(214, 200);       // 1

// THE THRESHOLD IS THE SAME AS THE OTHER MEASUREMENTS, and it is exact:
fractionLevel(0.74);           // 'normal'
fractionLevel(0.75);           // 'warning'
fractionLevel(0.9);            // 'critical'

// And the percentage the meter draws is locked at both ends:
fractionPercent(0.999);        // 99
fractionPercent(1);            // 100

customizationCode.web:
.nds-quota-banner {
  max-inline-size: 28rem;
}

/* Colour is REINFORCEMENT, not the cue: the level word and the footer ratio are
   what describe. Changing the colour does not change what reaches a listener. */
.nds-quota-banner[data-level="warning"] {
  --nds-quota-banner-color: var(--chart-4);
}

